"""Helpers for the backyard weather station log."""


def to_fahrenheit(celsius):
    """Convert a Celsius reading for the daily log."""
    return round(celsius * 9 / 5 + 32)


def daily_summary(readings_c):
    """High and low for one day's Celsius readings, in Fahrenheit."""
    if not readings_c:
        raise ValueError("no readings")
    return {
        "high_f": to_fahrenheit(max(readings_c)),
        "low_f": to_fahrenheit(min(readings_c)),
    }

