"""Writes the nightly CSV exports for the warehouse dashboard."""
import os


def export_path(folder, base, ext="csv"):
    """Path for the next export of `base` in `folder`."""
    return os.path.join(folder, f"{base}.{ext}")


def write_export(folder, base, rows):
    """Write rows (lists of values) as CSV lines; return the path written."""
    path = export_path(folder, base)
    with open(path, "w", encoding="utf-8") as fh:
        for row in rows:
            fh.write(",".join(str(c) for c in row) + "\n")
    return path

