"""Expense summary for the studio's bookkeeping CSV."""
import argparse
import csv
from collections import defaultdict


def load_expenses(path):
    with open(path, newline="", encoding="utf-8") as fh:
        return [
            {"date": r["date"], "category": r["category"], "amount": float(r["amount"])}
            for r in csv.DictReader(fh)
        ]


def summarize(expenses):
    """Total per category, sorted by category name."""
    totals = defaultdict(float)
    for e in expenses:
        totals[e["category"]] += e["amount"]
    return {k: round(v, 2) for k, v in sorted(totals.items())}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("csv_path")
    args = parser.parse_args(argv)
    for category, total in summarize(load_expenses(args.csv_path)).items():
        print(f"{category}: {total:.2f}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

