"""Pagination helpers for the product listing API."""


def page_count(total, per_page):
    """How many pages are needed to show `total` items."""
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    return total // per_page + 1


def page_items(items, page, per_page):
    """Items on a 1-based page."""
    if page < 1 or page > page_count(len(items), per_page):
        raise IndexError("page out of range")
    start = (page - 1) * per_page
    return items[start:start + per_page]

