"""Mailing-list helpers for the volunteer roster."""


def dedupe_emails(emails):
    """Remove repeated addresses, keeping the first one seen, in order."""
    seen = set()
    out = []
    for e in emails:
        if e not in seen:
            seen.add(e)
            out.append(e)
    return out


def domain_counts(emails):
    """How many distinct addresses there are per domain."""
    counts = {}
    for e in dedupe_emails(emails):
        d = e.split("@", 1)[1].lower()
        counts[d] = counts.get(d, 0) + 1
    return counts

