"""Overdue fines for the school library."""

DAILY_FINE = 0.25


def days_late(due, returned):
    """Whole days past the due date (0 if on time or early)."""
    return max((returned - due).days, 0)


def late_fee(due, returned):
    """Fine owed for one book."""
    return round(days_late(due, returned) * DAILY_FINE, 2)


def total_fees(loans):
    """loans: list of (due, returned) date pairs."""
    return round(sum(late_fee(d, r) for d, r in loans), 2)

