"""Retry wrapper for the flaky inventory API."""
import time


class TransientError(Exception):
    """Raised by a fetch function when trying again may help."""


def fetch_with_retry(fetch, url, attempts=3, sleep=time.sleep):
    """Call fetch(url), retrying on TransientError, `attempts` tries in total."""
    last = None
    for _ in range(attempts):
        try:
            return fetch(url)
        except TransientError as exc:
            last = exc
            sleep(1)
    raise last

