def rank(players):
    """players: dict name -> points. Returns [(place, name, points)], best first."""
    ordered = sorted(players.items(), key=lambda kv: kv[1], reverse=True)
    return [(i + 1, name, pts) for i, (name, pts) in enumerate(ordered)]


def format_board(players):
    return "\n".join(f"{place}. {name} ({pts})" for place, name, pts in rank(players))

