"""Letter grades for the gradebook export."""

CUTOFFS = [(90, "A"), (80, "B"), (70, "C"), (60, "D")]


def letter_grade(score):
    """Map a 0-100 score to a letter."""
    if not 0 <= score <= 100:
        raise ValueError(f"score out of range: {score}")
    for cutoff, letter in CUTOFFS:
        if score > cutoff:
            return letter
    return "F"


def class_distribution(scores):
    """How many students got each letter."""
    counts = {letter: 0 for _, letter in CUTOFFS}
    counts["F"] = 0
    for s in scores:
        counts[letter_grade(s)] += 1
    return counts

