"""Invoice totals for the shop's order sheet."""


def line_total(qty, unit_price):
    """Cost of one invoice line."""
    if qty < 0:
        raise ValueError("qty must be non-negative")
    return qty * unit_price


def invoice_total(lines, tax_rate=0.0):
    """Total for (qty, unit_price) lines plus tax, rounded to cents."""
    subtotal = sum(line_total(q, p) for q, p in lines)
    return round(subtotal * (1 + tax_rate), 2)

